import{_ as t,a0 as o,w as d,s as r,I as n,x as e,a1 as l,A as i,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"使用 Ansible 管理你的工作站：配置桌面设置 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Ansible 管理你的工作站：配置桌面设置 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Ansible 管理你的工作站：配置桌面设置 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Ansible 管理你的工作站：配置桌面设置 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20180529 Manage your workstation with Ansible- Configure desktop settings","title":"使用 Ansible 管理你的工作站：配置桌面设置","tag":"201907","desc":""},"relativePath":"201907/20180529 Manage your workstation with Ansible- Configure desktop settings.md","filePath":"[post].md"}'),u={name:"201907/20180529 Manage your workstation with Ansible- Configure desktop settings.md"};function g(c,s,k,b,h,m){const a=o("Link");return d(),r("div",null,[s[38]||(s[38]=n("h1",{id:"使用-ansible-管理你的工作站-配置桌面设置",tabindex:"-1"},[e("使用 Ansible 管理你的工作站：配置桌面设置 "),n("a",{class:"header-anchor",href:"#使用-ansible-管理你的工作站-配置桌面设置","aria-label":"Permalink to “使用 Ansible 管理你的工作站：配置桌面设置”"},"​")],-1)),s[39]||(s[39]=n("blockquote",null,[n("p",null,"在本系列第三篇（也是最后一篇）文章中，我们将使用 Ansible 自动化配置 GNOME 桌面设置。")],-1)),s[40]||(s[40]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/cube_innovation_process_block_container.png?itok=vkPYmSRQ",alt:""})],-1)),n("p",null,[s[2]||(s[2]=e("在本系列关于使用 Ansible 配置工作站的",-1)),l(a,{href:"https://linux.cn/article-10434-1.html"},{default:i(()=>[...s[0]||(s[0]=[e("第一篇文章",-1)])]),_:1}),s[3]||(s[3]=e("中，我们设置了一个仓库并配置了一些基本的东西。在",-1)),l(a,{href:"https://linux.cn/article-10449-1.html"},{default:i(()=>[...s[1]||(s[1]=[e("第二篇文章",-1)])]),_:1}),s[4]||(s[4]=e("中，我们配置了 Ansible 以使其在对仓库进行更改时自动应用设置。在第三篇（也是最后一篇）文章中，我们将使用 Ansible 配置 GNOME 桌面设置。",-1))]),s[41]||(s[41]=n("p",null,[e("此配置只适用于较新的发行版（例如我将在示例中使用的 Ubuntu 18.04）。较旧版本的 Ubuntu 将无法运行，因为它们附带了一个老版本的 "),n("code",null,"python-psutils"),e("，对于 Ansible 的 "),n("code",null,"dconf"),e(" 模块无法正常工作。如果你使用的是较新版本的 Linux 发行版，则应该没有问题。")],-1)),n("p",null,[s[6]||(s[6]=e("在开始之前，确保你已经完成了本系列的第一部分和第二部分，因为第三部分建立在此基础之上的。如果还没有，下载前两篇文章中一直使用的 GitHub ",-1)),l(a,{href:"https://github.com/jlacroix82/ansible_article.git"},{default:i(()=>[...s[5]||(s[5]=[e("仓库",-1)])]),_:1}),s[7]||(s[7]=e("，我们将为其添加更多功能。",-1))]),s[42]||(s[42]=p(`<h3 id="设置壁纸和锁屏" tabindex="-1">设置壁纸和锁屏 <a class="header-anchor" href="#设置壁纸和锁屏" aria-label="Permalink to “设置壁纸和锁屏”">​</a></h3><p>首先，我们将创建一个任务手册来保存我们的 GNOME 设置。在仓库的根目录中，应该有一个名为 <code>local.yml</code> 的文件，添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- include: tasks/gnome.yml</span></span></code></pre></div><p>整个文件应如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- hosts: localhost</span></span>
<span class="line"><span>  become: true</span></span>
<span class="line"><span>  pre_tasks:</span></span>
<span class="line"><span>    - name: update repositories</span></span>
<span class="line"><span>      apt: update_cache=yes</span></span>
<span class="line"><span>      changed_when: False</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - include: tasks/users.yml</span></span>
<span class="line"><span>    - include: tasks/cron.yml</span></span>
<span class="line"><span>    - include: tasks/packages.yml</span></span>
<span class="line"><span>    - include: tasks/gnome.yml</span></span></code></pre></div><p>基本上，这添加了对名为 <code>gnome.yml</code> 文件的引用，它将存储在仓库内的 <code>tasks</code> 目录中。我们还没有创建这个文件，现在就来创建它。在 <code>tasks</code> 目录中创建 <code>gnome.yml</code> 文件，并将以下内容放入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: Install python-psutil package</span></span>
<span class="line"><span>  apt: name=python-psutil</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Copy wallpaper file</span></span>
<span class="line"><span>  copy: src=files/wallpaper.jpg dest=/home/jay/.wallpaper.jpg owner=jay group=jay mode=600</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Set GNOME Wallpaper</span></span>
<span class="line"><span>  become_user: jay</span></span>
<span class="line"><span>  dconf: key=&quot;/org/gnome/desktop/background/picture-uri&quot; value=&quot;&#39;file:///home/jay/.wallpaper.jpg&#39;&quot;</span></span></code></pre></div><p>注意，此代码多次引用我的用户名（<code>jay</code>），因此确保使用你机器上的用户名替换每次出现的 <code>jay</code>。另外，如果你没有像我一样使用 Ubuntu 18.04，你将必须更改 <code>apt</code> 一行来匹配你所选择的发行版的包管理器，并确认 <code>python-psutil</code> 包的名称，因为它可能有所不同。</p>`,8)),n("p",null,[s[9]||(s[9]=e("在示例任务中，我引用了 ",-1)),s[10]||(s[10]=n("code",null,"file",-1)),s[11]||(s[11]=e(" 目录下的 ",-1)),s[12]||(s[12]=n("code",null,"wallpaper.jpg",-1)),s[13]||(s[13]=e(" 文件，此文件必须存在，否则 Ansible 配置将失败。在 ",-1)),s[14]||(s[14]=n("code",null,"tasks",-1)),s[15]||(s[15]=e(" 目录中，创建一个名为 ",-1)),s[16]||(s[16]=n("code",null,"files",-1)),s[17]||(s[17]=e(" 的子目录。找到你喜欢的壁纸图片，将其命名为 ",-1)),s[18]||(s[18]=n("code",null,"wallpaper.jpg",-1)),s[19]||(s[19]=e("，然后把它放在 ",-1)),s[20]||(s[20]=n("code",null,"files",-1)),s[21]||(s[21]=e(" 目录中。如果文件是 PNG 图像而不是 JPG，在代码和仓库中更改文件扩展名。如果你觉得没有创意，我在 ",-1)),l(a,{href:"https://github.com/jlacroix82/ansible_article.git"},{default:i(()=>[...s[8]||(s[8]=[e("GitHub 仓库",-1)])]),_:1}),s[22]||(s[22]=e(" 中有一个示例壁纸文件，你可以使用它。",-1))]),s[43]||(s[43]=p(`<p>完成所有这些更改后，将内容提交到 GitHub 仓库，并推送这些更改。总结一下，你应该完成以下工作：</p><ul><li>修改 <code>local.yml</code> 文件以引用 <code>tasks/gnome.yml</code></li><li>使用上面提到的内容创建 <code>tasks/gnome.yml</code></li><li>在 <code>tasks</code> 目录中创建一个 <code>files</code> 目录，其中有一个名为 <code>wallpaper.jpg</code> 的图像文件（或者你选择的任何名称）。</li></ul><p>完成这些步骤并将更改推送到仓库后，配置应该在下次计划运行期间自动应用。（你可能还记得我们在上一篇文章中对此进行了自动化。）如果你想节省时间，可以使用以下命令立即应用配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ansible-pull -U https://github.com/&lt;github_user&gt;/ansible.git</span></span></code></pre></div><p>如果一切正常，你应该可以看到你的新壁纸。</p><p>让我们花一点时间来了解新的 GNOME 任务手册的功能。首先，我们添加了一个计划来安装 <code>python-psutil</code> 包。如果不添加它，我们就不能使用 <code>dconf</code> 模块，因为它需要在修改 GNOME 设置之前安装这个包。接下来，我们使用 <code>copy</code> 模块将壁纸文件复制到我们的 <code>home</code> 目录，并将生成的文件命名为以点开头的隐藏文件。如果你不希望此文件放在 <code>home</code> 目录的根目录中，你可以随时指示此部分将其复制到其它位置 —— 只要你在正确的位置引用它，它仍然可以工作。在下一个计划中，我们使用 <code>dconf</code> 模块来更改 GNOME 设置。在这种情况下，我们调整了 <code>/org/gnome/desktop/background/picture-uri</code> 键并将其设置为 <code>file:///home/jay/.wallpaper.jpg</code>。注意本节中的引号 —— 你必须在 <code>dconf</code> 值中使用两个单引号，如果值是一个字符串，还必须包含在双引号内。</p><p>现在，让我们进一步进行配置，并将背景应用于锁屏。这是现在的 GNOME 任务手册，但增加了两个额外的计划：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: Install python-psutil package</span></span>
<span class="line"><span>  apt: name=python-psutil</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Copy wallpaper file</span></span>
<span class="line"><span>  copy: src=files/wallpaper.jpg dest=/home/jay/.wallpaper.jpg owner=jay group=jay mode=600</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Set GNOME wallpaper</span></span>
<span class="line"><span>  dconf: key=&quot;/org/gnome/desktop/background/picture-uri&quot; value=&quot;&#39;file:///home/jay/.wallpaper.jpg&#39;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Copy lockscreenfile</span></span>
<span class="line"><span>  copy: src=files/lockscreen.jpg dest=/home/jay/.lockscreen.jpg owner=jay group=jay mode=600</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Set lock screen background</span></span>
<span class="line"><span>  become_user: jay</span></span>
<span class="line"><span>  dconf: key=&quot;/org/gnome/desktop/screensaver/picture-uri&quot; value=&quot;&#39;file:///home/jay/.lockscreen.jpg&#39;&quot;</span></span></code></pre></div><p>正如你所看到的，我们做的事情和设置壁纸时差不多。我们添加了两个额外的任务，一个是复制锁屏图像并将其放在我们的 <code>home</code> 目录中，另一个是将设置应用于 GNOME 以便使用它。同样，确保将 <code>jay</code> 更改为你的用户名，并命名你想要的锁屏图片 <code>lockscreen.jpg</code>，并将其复制到 <code>files</code> 目录。将这些更改提交到仓库后，在下一次计划的 Ansible 运行期间就会应用新的锁屏。</p><h3 id="应用新的桌面主题" tabindex="-1">应用新的桌面主题 <a class="header-anchor" href="#应用新的桌面主题" aria-label="Permalink to “应用新的桌面主题”">​</a></h3><p>设置壁纸和锁屏背景很酷，但是让我们更进一步来应用桌面主题。首先，让我们在我们的任务手册中添加一条指令来安装 <code>arc</code> 主题的包。将以下代码添加到 GNOME 任务手册的开头：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: Install arc theme</span></span>
<span class="line"><span>  apt: name=arc-theme</span></span></code></pre></div><p>然后，在底部，添加以下动作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: Set GTK theme</span></span>
<span class="line"><span>  become_user: jay</span></span>
<span class="line"><span>  dconf: key=&quot;/org/gnome/desktop/interface/gtk-theme&quot; value=&quot;&#39;Arc&#39;&quot;</span></span></code></pre></div><p>你看到 GNOME 的 GTK 主题在你眼前变化了吗？我们添加了一个动作来通过 <code>apt</code> 模块安装 <code>arc-theme</code> 包，另一个动作将这个主题应用到 GNOME。</p><h3 id="进行其它定制" tabindex="-1">进行其它定制 <a class="header-anchor" href="#进行其它定制" aria-label="Permalink to “进行其它定制”">​</a></h3><p>既然你已经更改了一些 GNOME 设置，你可以随意添加其它定制。你在 GNOME 中调整的任何设置都可以通过这种方式自动完成，设置壁纸和主题只是几个例子。你可能想知道如何找到要更改的设置，以下是一个我用的技巧。</p><p>首先，通过在你管理的计算机上运行以下命令，获取所有当前 <code>dconf</code> 设置的快照：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dconf dump / &gt; before.txt</span></span></code></pre></div><p>此命令将所有当前更改导出到名为 <code>before.txt</code> 的文件中。接下来，手动更改要自动化的设置，并再次获取 <code>dconf</code> 设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dconf dump / &gt; after.txt</span></span></code></pre></div><p>现在，你可以使用 <code>diff</code> 命令查看两个文件之间的不同之处：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>diff before.txt after.txt</span></span></code></pre></div><p>这应该会给你一个已更改键值的列表。虽然手动更改设置确实违背了自动化的目的，但你实际上正在做的是获取更新首选设置时更改的键，这允许你创建 Ansible 任务以修改这些设置，这样你就再也不需要碰这些设置了。如果你需要还原机器，Ansible 仓库会处理好你的每个定制。如果你有多台计算机，甚至是一组工作站，则只需手动进行一次更改，所有其他工作站都将应用新设置并完全同步。</p><h3 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to “最后”">​</a></h3><p>如果你已经阅读完本系列文章，你应该知道如何设置 Ansible 来自动化工作站。这些示例提供了一个有用的基础，你可以使用这些语法和示例进行其他定制。随着你的进展，你可以继续添加新的修改，这将使你的 Ansible 配置一直增长。</p><p>我已经用 Ansible 以这种方式自动化了一切，包括我的用户帐户和密码、Vim、tmux 等配置文件、桌面包、SSH 设置、SSH 密钥，基本上我想要自定义的一切都使用了。以本系列文章作为起点，将为你实现工作站的完全自动化铺平道路。</p><hr>`,28)),n("p",null,[s[24]||(s[24]=e("via: ",-1)),l(a,{href:"https://opensource.com/article/18/5/manage-your-workstation-ansible-part-3"},{default:i(()=>[...s[23]||(s[23]=[e("https://opensource.com/article/18/5/manage-your-workstation-ansible-part-3",-1)])]),_:1})]),n("p",null,[s[29]||(s[29]=e("作者：",-1)),l(a,{href:"https://opensource.com/users/jlacroix"},{default:i(()=>[...s[25]||(s[25]=[e("Jay LaCroix",-1)])]),_:1}),s[30]||(s[30]=e(" 选题：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[26]||(s[26]=[e("lujun9972",-1)])]),_:1}),s[31]||(s[31]=e(" 译者：",-1)),l(a,{href:"https://github.com/MjSeven"},{default:i(()=>[...s[27]||(s[27]=[e("MjSeven",-1)])]),_:1}),s[32]||(s[32]=e(" 校对：",-1)),l(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[28]||(s[28]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[35]||(s[35]=e("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[33]||(s[33]=[e("LCTT",-1)])]),_:1}),s[36]||(s[36]=e(" 原创编译，",-1)),l(a,{href:"https://linux.cn/"},{default:i(()=>[...s[34]||(s[34]=[e("Linux中国",-1)])]),_:1}),s[37]||(s[37]=e(" 荣誉推出",-1))])])}const j=t(u,[["render",g]]);export{C as __pageData,j as default};
